int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    mp_int maxOrder = {0};

    if (!rng || !k || !order) {
        return BAD_FUNC_ARG;
    }

    if (size <= 0) {
        return BAD_FUNC_ARG;
    }

    randBytes = (byte*)malloc(size);
    if (!randBytes) {
        return MEMORY_E;
    }

    ret = wc_RNG_GenerateBlock(rng, randBytes, size);
    if (ret != 0) {
        free(randBytes);
        return ret;
    }

    mp_init(&maxOrder);
    mp_read_unsigned_octet(&maxOrder, randBytes, size);

    if (mp_cmp(&maxOrder, order) >= 0) {
        mp_sub_d(order, 1, &maxOrder);
    }

    if (mp_cmp_d(&maxOrder, 0) <= 0) {
        mp_set_int(&maxOrder, 1);
    }

    mp_copy(&maxOrder, k);

    mp_clear(&maxOrder);
    free(randBytes);

    return 0;
}
